layer.css:
[data-ryt="footer"] { color: var(--ryt-text); border-top: 1px solid rgb(224, 221, 216); font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { border-bottom: 1px solid rgb(224, 221, 216); border-radius: 0px; transition: all; border-top: none; border-right: none; border-left: none }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 5px; font-family: system-ui, "Segoe UI", Roboto, Oxygen, Ubuntu, Cantarell, Helvetica, Arial, "Helvetica Neue", sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; font-size: 20px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: 2.5px; transition: color 0.2s, background-color 0.2s, border-color 0.2s, text-decoration-color 0.2s, opacity 0.2s }
[data-ryt="nav"] a { color: var(--ryt-text); border-radius: 5px; font-family: system-ui, "Segoe UI", Roboto, Oxygen, Ubuntu, Cantarell, Helvetica, Arial, "Helvetica Neue", sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; font-size: 20px; font-weight: 700; font-style: normal; line-height: 1.125; letter-spacing: -1px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: 6.25px; padding-top: 10px; padding-right: 10px; padding-bottom: 10px; padding-left: 10px; transition: color 0.2s, background-color 0.2s, border-color 0.2s, text-decoration-color 0.2s, opacity 0.2s }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-text); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: color-mix(in srgb, var(--ryt-text) 40%, transparent); text-decoration-thickness: auto; text-underline-offset: 2.08333px; transition: color 0.2s, background-color 0.2s, border-color 0.2s, text-decoration-color 0.2s, opacity 0.2s }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-muted); font-family: system-ui, "Segoe UI", Roboto, Oxygen, Ubuntu, Cantarell, Helvetica, Arial, "Helvetica Neue", sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; font-size: 17px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: 2px; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-radius: 0px; font-family: system-ui, "Segoe UI", Roboto, Oxygen, Ubuntu, Cantarell, Helvetica, Arial, "Helvetica Neue", sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; font-weight: 500; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: 2.5px; transition: color 0.2s, background-color 0.2s, border-color 0.2s, text-decoration-color 0.2s, opacity 0.2s }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: system-ui, "Segoe UI", Roboto, Oxygen, Ubuntu, Cantarell, Helvetica, Arial, "Helvetica Neue", sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; font-size: 20px; font-weight: 500; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: 2.5px; transition: color 0.2s, background-color 0.2s, border-color 0.2s, text-decoration-color 0.2s, opacity 0.2s }
[data-ryt="rec-card"] [data-ryt="title"]:hover { text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: color-mix(in srgb, var(--ryt-text) 40%, transparent); text-underline-offset: 0.15em; opacity: 1 }
body:hover { opacity: 1 }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: color-mix(in srgb, var(--ryt-text) 40%, transparent); text-underline-offset: 0.15em; opacity: 1 }
[data-ryt="credit"]:hover, [data-ryt="eyebrow"]:hover { opacity: 1 }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { opacity: 1 }
[data-ryt="header"]:hover { opacity: 1 }
[data-ryt="nav"] a:hover { opacity: 1 }
[data-ryt="brand"]:hover { opacity: 1 }
article[data-ryt="rec-card"]:hover { opacity: 1 }
[data-ryt="footer"]:hover { opacity: 1 }
